def transform_vertical_band(grid):
    h_in, w_in = len(grid), len(grid[0])
    h_out, w_out = min(h_in-1, 21), 17

    output = [[9 for _ in range(w_out)] for _ in range(h_out)]

    for i in range(h_out):
        for j in range(w_out):
            # Look at input column j+1 in rows i+1 to i+6
            seen = {}  # color -> True if seen
            for ri in range(i+1, min(i+7, h_in)):
                if 0 <= j + 1 < w_in:
                    col = grid[ri][j+1]
                    if col in [2, 4, 6, 8]:
                        seen[col] = True
                    elif col in [0, 1, 5, 7]:
                        # Noise... treat as background
                        pass

            if seen:
                # Most frequent? Most recent? Let's try most recent (last seen)
                for ri in range(min(i+6, h_in), i, -1):
                    if 0 <= j + 1 < w_in:
                        val = grid[ri][j+1]
                        if val in [2, 4, 6, 8]:
                            output[i][j] = val
                            break

    matches = sum(1 for i in range(h_out) for j in range(w_out) if output[i][j] == demo_output[i][j])
    total = h_out * w_out
    print(f"Vertical band (most recent): {matches}/{total} = {matches/total:.2%}")

    # Try first seen instead
    output2 = [[9 for _ in range(w_out)] for _ in range(h_out)]
    for i in range(h_out):
        for j in range(w_out):
            for ri in range(i+1, min(i+7, h_in)):
                if 0 <= j + 1 < w_in:
                    val = grid[ri][j+1]
                    if val in [2, 4, 6, 8] and output2[i][j] == 9:
                        output2[i][j] = val

    matches2 = sum(1 for i in range(h_out) for j in range(w_out) if output2[i][j] == demo_output[i][j])
    print(f"Vertical band (first): {matches2}/{total} = {matches2/total:.2%}")

    # Try: priority by color order (2 beats 6, 8 beats 2, etc)
    output3 = [[9 for _ in range(w_out)] for _ in range(h_out)]
    priority = {8: 100, 6: 50, 4: 40, 2: 30}  # 8 strongest, then 6, etc
    for i in range(h_out):
        for j in range(w_out):
            best_color = None
            for ri in range(i+1, min(i+7, h_in)):
                if 0 <= j + 1 < w_in:
                    val = grid[ri][j+1]
                    if val in [2, 4, 6, 8]:
                        if best_color is None or priority[val] > priority[best_color]:
                            best_color = val
            if best_color:
                output3[i][j] = best_color

    matches3 = sum(1 for i in range(h_out) for j in range(w_out) if output3[i][j] == demo_output[i][j])
    print(f"Vertical band (priority): {matches3}/{total} = {matches3/total:.2%}")

